13: export function validateCourse(course: CourseDefinition): void {
14:   if (!course.id.trim()) throw new Error('Course id must not be empty');
15:   if (!course.name.trim()) throw new Error(`Course ${course.id}: name must not be empty`);
16:   if (!course.themeId.trim()) throw new Error(`Course ${course.id}: themeId must not be empty`);
17:   if (!Number.isInteger(course.version) || course.version < 1) {
18:     throw new Error(`Course ${course.id}: version must be a positive integer`);
19:   }
20:   if (course.holes.length === 0) throw new Error(`Course ${course.id}: at least one hole is required`);
